namespace Atc.Rest.Api.Generator.Tests.Helpers;

/// <summary>
/// A generated file brings its own usings for the namespaces the SDK's implicit usings would otherwise supply, so it
/// compiles in a project with <c>ImplicitUsings</c> off: <c>System</c>, and each other one whose types (or LINQ's
/// extension methods) it names.
/// </summary>
public class ImplicitUsingsHelperTests
{
    private const string AllSeven =
        "using System;\nusing System.Collections.Generic;\nusing System.IO;\nusing System.Linq;\nusing System.Net.Http;\nusing System.Threading;\nusing System.Threading.Tasks;\n";

    // Code that uses a type of every implicit namespace
    private const string UsesAll =
        "public static class C { public static Task<List<int>> M(Stream s, HttpClient c, CancellationToken t) => Task.FromResult(new[] { 1 }.Select(x => x).ToList()); }\n";

    [Fact]
    public void AddImplicitUsings_BeforeTheFirstUsing_AfterTheHeader()
    {
        var content = "// <auto-generated />\n#nullable enable\n\nusing System.CodeDom.Compiler;\n\nnamespace Foo;\n" + UsesAll;

        var result = ImplicitUsingsHelper.AddImplicitUsings(content);

        Assert.Equal("// <auto-generated />\n#nullable enable\n\n" + AllSeven + "using System.CodeDom.Compiler;\n\nnamespace Foo;\n" + UsesAll, result);
    }

    [Fact]
    public void AddImplicitUsings_WithoutUsings_BeforeTheNamespace_WithABlankLine()
    {
        var content = "// <auto-generated />\n#nullable enable\n\nnamespace Foo;\n" + UsesAll;

        var result = ImplicitUsingsHelper.AddImplicitUsings(content);

        Assert.Equal("// <auto-generated />\n#nullable enable\n\n" + AllSeven + "\nnamespace Foo;\n" + UsesAll, result);
    }

    [Fact]
    public void AddImplicitUsings_SkipsANamespaceTheFileImportsAlready()
    {
        var content = "#nullable enable\nusing System.Linq;\nusing System;\n\nnamespace Foo;\n" + UsesAll;

        var result = ImplicitUsingsHelper.AddImplicitUsings(content);

        Assert.Equal(
            "#nullable enable\nusing System.Collections.Generic;\nusing System.IO;\nusing System.Net.Http;\nusing System.Threading;\nusing System.Threading.Tasks;\nusing System.Linq;\nusing System;\n\nnamespace Foo;\n" + UsesAll,
            result);
    }

    [Fact]
    public void AddImplicitUsings_AfterGlobalUsings_WhichMustComeFirst()
    {
        var content = "// <auto-generated />\nglobal using System;\nglobal using global::System.Linq;\n\nnamespace Foo;\n" + UsesAll;

        var result = ImplicitUsingsHelper.AddImplicitUsings(content);

        Assert.Equal(
            "// <auto-generated />\nglobal using System;\nglobal using global::System.Linq;\n\nusing System.Collections.Generic;\nusing System.IO;\nusing System.Net.Http;\nusing System.Threading;\nusing System.Threading.Tasks;\n\nnamespace Foo;\n" + UsesAll,
            result);
    }

    [Theory]
    [InlineData("public sealed record Pet(long Id, string Name);", "using System;\n")]
    [InlineData("public sealed record Page(List<Pet> Items);", "using System;\nusing System.Collections.Generic;\n")]
    [InlineData("public interface IHandler { Task<int> ExecuteAsync(CancellationToken cancellationToken); }", "using System;\nusing System.Threading;\nusing System.Threading.Tasks;\n")]
    [InlineData("public static class C { public static int N(int[] a) => a.Count(x => x > 1); }", "using System;\nusing System.Linq;\n")]
    [InlineData("public static class C { public static int N(int[] a) => (from x in a select x).Sum(); }", "using System;\nusing System.Linq;\n")]
    [InlineData("public sealed record F(Stream Content);", "using System;\nusing System.IO;\n")]
    [InlineData("public sealed class E(HttpClient client);", "using System;\nusing System.Net.Http;\n")]
    public void AddImplicitUsings_AddsSystem_AndTheNamespacesTheCodeUses(
        string code,
        string usings)
    {
        var content = "namespace Foo;\n" + code + "\n";

        var result = ImplicitUsingsHelper.AddImplicitUsings(content);

        Assert.Equal(usings + "\nnamespace Foo;\n" + code + "\n", result);
    }

    [Fact]
    public void AddImplicitUsings_AFileWithoutCode_StaysAsItIs()
    {
        var content = "// <auto-generated />\n#pragma warning disable CS1591\nglobal using Foo.Handlers;\nglobal using System;";

        Assert.Equal(content, ImplicitUsingsHelper.AddImplicitUsings(content));
    }

    [Fact]
    public void AddImplicitUsings_KeepsTheFilesLineEndings()
    {
        var content = "#nullable enable\r\n\r\nnamespace Foo;\r\n" + UsesAll.Replace("\n", "\r\n", StringComparison.Ordinal);

        var result = ImplicitUsingsHelper.AddImplicitUsings(content);

        Assert.Equal("#nullable enable\r\n\r\n" + AllSeven.Replace("\n", "\r\n", StringComparison.Ordinal) + "\r\nnamespace Foo;\r\n" + UsesAll.Replace("\n", "\r\n", StringComparison.Ordinal), result);
    }

    [Fact]
    public void AddImplicitUsings_IsAppliedOnce()
    {
        var once = ImplicitUsingsHelper.AddImplicitUsings("namespace Foo;\n" + UsesAll);

        Assert.Equal(once, ImplicitUsingsHelper.AddImplicitUsings(once));
    }

    [Fact]
    public void AddImplicitUsings_AnEmptyFile_StaysEmpty()
        => Assert.Equal(string.Empty, ImplicitUsingsHelper.AddImplicitUsings(string.Empty));
}